<script lang="ts">
  import { Activity, ArrowLeft, Database, FileWarning, HardDrive, LayoutDashboard, Search, ShieldCheck, Users } from '@lucide/svelte';
  let { data, form } = $props();
  let activeView = $state<'overview' | 'users' | 'moderation' | 'system'>('overview');
  const formatBytes = (bytes: number) => bytes < 1024 * 1024 ? `${(bytes / 1024).toFixed(1)} KB` : bytes < 1024 ** 3 ? `${(bytes / 1024 ** 2).toFixed(1)} MB` : `${(bytes / 1024 ** 3).toFixed(2)} GB`;
  const date = (value: Date | null) => value ? value.toLocaleString('nb-NO', { dateStyle: 'short', timeStyle: 'short' }) : 'Aldri';
  const reasonLabels: Record<string, string> = { spam: 'Spam', harassment: 'Trakassering', sexual: 'Seksuelt innhold', violence: 'Vold', privacy: 'Personvern', other: 'Annet' };
</script>

<svelte:head><title>Admin – Samvio</title><meta name="robots" content="noindex,nofollow"/></svelte:head>

<main class="admin-page">
  <aside class="admin-nav">
    <a class="admin-brand" href="/"><span>S</span><div><strong>Samvio</strong><small>Administrasjon</small></div></a>
    <nav aria-label="Adminområder">
      <button class:active={activeView === 'overview'} onclick={() => activeView = 'overview'}><LayoutDashboard size={19}/>Oversikt</button>
      <button class:active={activeView === 'users'} onclick={() => activeView = 'users'}><Users size={19}/>Brukere</button>
      <button class:active={activeView === 'moderation'} onclick={() => activeView = 'moderation'}><FileWarning size={19}/>Moderering{#if data.stats.reports}<span class="count">{data.stats.reports}</span>{/if}</button>
      <button class:active={activeView === 'system'} onclick={() => activeView = 'system'}><Database size={19}/>System</button>
    </nav>
    <a class="back" href="/"><ArrowLeft size={17}/>Tilbake til Samvio</a>
  </aside>

  <section class="admin-content">
    <header class="topbar"><div><span>Samvio kontrollrom</span><h1>{activeView === 'overview' ? 'Oversikt' : activeView === 'users' ? 'Brukerbehandling' : activeView === 'moderation' ? 'Moderering' : 'System og lagring'}</h1><p>Innlogget som {data.admin.realName}</p></div><div class="healthy"><i></i>Systemet kjører</div></header>
    {#if form?.adminError}<div class="notice error" role="alert">{form.adminError}</div>{:else if form?.adminSuccess}<div class="notice success">{form.adminSuccess}</div>{/if}

    {#if activeView === 'overview'}
      <section class="stat-grid">
        <article><span><Activity size={18}/></span><p>Aktive brukere 24t</p><strong>{data.stats.active24}</strong><small>Basert på siste aktivitet</small></article>
        <article><span><Users size={18}/></span><p>Registrerte brukere</p><strong>{data.stats.users}</strong><small>Alle kontoer</small></article>
        <article><span><LayoutDashboard size={18}/></span><p>Totalt antall innlegg</p><strong>{data.stats.posts}</strong><small>Kronologiske øyeblikk</small></article>
        <article class:attention={data.stats.reports}><span><FileWarning size={18}/></span><p>Åpne rapporter</p><strong>{data.stats.reports}</strong><small>Venter på behandling</small></article>
      </section>
      <section class="overview-grid"><article class="panel"><header><div><ShieldCheck size={20}/><h2>Systemstatus</h2></div><span class="status good">Operativ</span></header><div class="status-list"><p><span>Applikasjon</span><strong>På nett</strong></p><p><span>Database</span><strong>Tilkoblet</strong></p><p><span>Bildeopplasting</span><strong>Maks 25 MB</strong></p><p><span>Feed</span><strong>Kronologisk</strong></p></div></article><article class="panel"><header><div><HardDrive size={20}/><h2>Lagring</h2></div><span>{formatBytes(data.storage.bytes)}</span></header><div class="storage-bar"><i style={`width:${Math.min(100, data.storage.bytes / data.storage.limitBytes * 100)}%`}></i></div><p class="muted">{formatBytes(data.storage.bytes)} brukt av omtrent {formatBytes(data.storage.limitBytes)} diskplass.</p></article></section>
    {:else if activeView === 'users'}
      <section class="panel"><header class="table-head"><div><Users size={20}/><h2>Brukere</h2><span>{data.users.length} vist</span></div><form method="GET"><Search size={17}/><input name="q" value={data.query} placeholder="Søk etter navn, @bruker eller e-post"/><button>Søk</button></form></header><div class="table-wrap"><table><thead><tr><th>Bruker</th><th>Medlemskap</th><th>Status</th><th>Sist aktiv</th><th>Rolle</th><th>Handlinger</th></tr></thead><tbody>{#each data.users as user}<tr><td><strong>{user.realName}</strong><small>@{user.username}<br/>{user.email}</small></td><td><span class:subscriber={user.subscriber} class="pill">{user.subscriber ? 'Vipps' : 'Gratis'}</span></td><td><span class:suspended={user.status === 'suspended'} class="pill">{user.status === 'suspended' ? 'Utestengt' : user.mutedUntil && user.mutedUntil > new Date() ? 'Dempet' : 'Aktiv'}</span></td><td>{date(user.lastSeenAt)}</td><td><form method="POST" action="?/userAction" class="role-form"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value="role"/><select name="role" aria-label={`Rolle for ${user.realName}`}><option value="user" selected={user.role === 'user'}>Bruker</option><option value="moderator" selected={user.role === 'moderator'}>Moderator</option><option value="admin" selected={user.role === 'admin'}>Admin</option></select><button>Lagre</button></form></td><td><div class="row-actions"><form method="POST" action="?/userAction"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value={user.mutedUntil && user.mutedUntil > new Date() ? 'unmute' : 'mute'}/><button>{user.mutedUntil && user.mutedUntil > new Date() ? 'Opphev mute' : 'Mute 24t'}</button></form><form method="POST" action="?/userAction"><input type="hidden" name="userId" value={user.id}/><input type="hidden" name="operation" value={user.status === 'suspended' ? 'unban' : 'ban'}/><button class="danger">{user.status === 'suspended' ? 'Opphev ban' : 'Ban'}</button></form></div></td></tr>{/each}</tbody></table></div></section>
    {:else if activeView === 'moderation'}
      <section class="panel"><header><div><FileWarning size={20}/><h2>Rapportkø</h2></div><span class="pill">{data.reports.length} rapporter</span></header>{#if data.reports.length}<div class="table-wrap"><table><thead><tr><th>Rapport</th><th>Innhold</th><th>Innmelder</th><th>Status</th><th>Handlinger</th></tr></thead><tbody>{#each data.reports as report}<tr><td><strong>{reasonLabels[report.reason]}</strong><small>{report.details || 'Ingen tilleggsinformasjon'}<br/>{date(report.createdAt)}</small></td><td><span class="type">{report.targetType}</span><strong>{report.target?.author || 'Slettet innhold'}</strong><small>{report.target?.text || report.targetId}</small></td><td>{report.reporterName}<small>@{report.reporterUsername}</small></td><td><span class:open={report.status === 'open'} class="pill">{report.status}</span></td><td><div class="row-actions">{#each [['approve','Godkjenn'],['hide','Skjul'],['delete','Slett']] as action}<form method="POST" action="?/moderate"><input type="hidden" name="reportId" value={report.id}/><input type="hidden" name="operation" value={action[0]}/><button class:danger={action[0] === 'delete'} disabled={report.status !== 'open'}>{action[1]}</button></form>{/each}</div></td></tr>{/each}</tbody></table></div>{:else}<div class="empty"><ShieldCheck size={34}/><h2>Rapportkøen er tom</h2><p>Ingen innholdselementer venter på behandling.</p></div>{/if}</section>
    {:else}
      <section class="system-grid"><article class="panel system-card"><HardDrive size={27}/><div><span>Opplastede bilder</span><strong>{formatBytes(data.storage.bytes)}</strong><p>Innlegg, profilbilder og forsidebilder på lokal disk.</p></div><div class="storage-bar"><i style={`width:${Math.min(100, data.storage.bytes / data.storage.limitBytes * 100)}%`}></i></div></article><article class="panel system-card"><Database size={27}/><div><span>Database</span><strong>Tilkoblet</strong><p>MySQL/MariaDB svarer og dashboarddata er hentet.</p></div></article><article class="panel system-card"><ShieldCheck size={27}/><div><span>Opplastingsgrenser</span><strong>25 MB</strong><p>Bilder komprimeres i nettleseren til omtrent 1–3 MB før sending.</p></div></article></section>
    {/if}
  </section>
</main>

<style>
