);font-size:11px;font-weight:800}.healthy i{width:7px;height:7px;border-radius:50%;background:#65a37f;box-shadow:0 0 0 4px #e2f0e7}.stat-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}.stat-grid article,.panel{border:1px solid var(--line);border-radius:16px;background:#fff;box-shadow:0 10px 28px #26382f0a}.stat-grid article{padding:18px}.stat-grid article>span{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:#e8f0eb;color:var(--green)}.stat-grid article.attention>span{background:#faeee6;color:var(--orange)}.stat-grid p{margin:15px 0 5px;color:#6b706c;font-size:11px}.stat-grid strong{display:block;font:600 31px 'Newsreader',serif}.stat-grid small{color:#979b97;font-size:10px}.overview-grid,.system-grid{display:grid;grid-template-columns:1.3fr 1fr;gap:14px;margin-top:14px}.panel{overflow:hidden}.panel>header{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:16px 18px;border-bottom:1px solid #ebe7df}.panel>header>div{display:flex;align-items:center;gap:9px}.panel h2{margin:0;font-size:14px}.status,.pill{display:inline-flex;padding:5px 8px;border:1px solid #d8dcd8;border-radius:999px;background:#f7f8f7;color:#5f6561;font-size:9px;font-weight:800}.status.good,.pill.subscriber{border-color:#bdd3c5;background:#e8f3ec;color:var(--green)}.pill.suspended,.row-actions .danger{border-color:#ebc1b9;background:#fff0ed;color:#9b3c2d}.pill.open{border-color:#e8cfad;background:#fff7e9;color:#8c5a21}.status-list{padding:5px 18px}.status-list p{display:flex;justify-content:space-between;margin:0;padding:12px 0;border-bottom:1px solid #efede7;font-size:12px}.status-list span{color:#737873}.panel>.muted{padding:15px 18px}.storage-bar{height:9px;margin:24px 18px 5px;overflow:hidden;border-radius:99px;background:#e9ece9}.storage-bar i{display:block;height:100%;min-width:3px;border-radius:inherit;background:linear-gradient(90deg,var(--green),#73a68a)}.notice{margin-bottom:16px;padding:12px 14px;border-radius:11px;font-size:12px}.notice.error{background:#fff0ed;color:#9b3c2d}.notice.success{background:#e8f3ec;color:var(--green)}.table-head{align-items:center}.table-head form{display:flex;align-items:center;gap:7px;width:min(430px,100%);padding:5px 6px 5px 11px;border:1px solid var(--line);border-radius:10px}.table-head input{min-width:0;flex:1;border:0;outline:0;background:transparent}.table-head button,.row-actions button,.role-form button{padding:7px 10px;border:1px solid #cdd6d0;border-radius:8px;background:#edf3ef;color:var(--green-dark);font-size:10px;font-weight:800}.table-wrap{overflow:auto;max-height:calc(100vh - 210px)}table{width:100%;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #ece9e2;text-align:left;vertical-align:top;font-size:11px}th{position:sticky;top:0;background:#faf9f6;color:#707570;font-size:9px;text-transform:uppercase;letter-spacing:.08em}td>strong,td>small{display:block}td small{max-width:250px;margin-top:3px;color:#818681;line-height:1.45}.row-actions{display:flex;flex-wrap:wrap;gap:5px}.role-form{display:flex;gap:5px}.role-form select{padding:7px;border:1px solid var(--line);border-radius:8px;background:#fff;font-size:10px}.type{display:block;margin-bottom:4px;color:var(--orange);font-size:9px;font-weight:800;text-transform:uppercase}.empty{min-height:330px;display:grid;place-items:center;align-content:center;gap:7px;color:#737873;text-align:center}.empty h2{margin:6px 0 0;color:#252a27}.empty p{margin:0;font-size:12px}.system-grid{grid-template-columns:repeat(3,1fr);margin:0}.system-card{display:grid;gap:14px;padding:22px;color:var(--green)}.system-card span{color:#737873;font-size:10px;text-transform:uppercase}.system-card strong{display:block;margin:4px 0;font:600 27px 'Newsreader',serif;color:#202522}.system-card p{margin:0;color:#707570;font-size:11px;line-height:1.5}.system-card .storage-bar{margin:4px 0 0}@media(max-width:980px){.admin-nav{position:static;width:auto;min-height:0}.admin-nav nav{display:flex;overflow:auto}.admin-nav button{width:auto;flex:none}.back{display:none}.admin-content{margin:0;padding:24px 15px 90px}.stat-grid{grid-template-columns:repeat(2,1fr)}.overview-grid,.system-grid{grid-template-columns:1fr}}@media(max-width:560px){.topbar{align-items:flex-start}.healthy{display:none}.stat-grid{grid-template-columns:1fr 1fr}.stat-grid article{padding:14px}.table-head{align-items:flex-start;flex-direction:column}.table-head form{width:100%}}
</style>
